function buySoulShopItem(itemId) {
    var item = SOUL_SHOP_ITEMS.find(i => i.id === itemId);
    if (!item) return false;

    var currentLevel = G.soulShopLevels ? (G.soulShopLevels[itemId] || 0) : 0;

