                matches = effect.type === 'building' || effect.type === 'global';
                break;
            case 'boss':
                matches = effect.type === 'boss' || effect.type === 'global';
                break;
            case 'rebirth':
                matches = effect.type === 'rebirth' || effect.type === 'global';
                break;
        }

        if (matches) {
            bonus += effect.value;
        }
    });

    return bonus;
}
